  'assoc_mlm_faq_title' => 'अक्सर पूछे जाने वाले प्रश्न',
  'assoc_mlm_faq1_q' => 'मैं एसोसिएट के रूप में कैसे रजिस्टर करूं?',
  'assoc_mlm_faq1_a' => '"एसोसिएट के रूप में रजिस्टर करें" पर क्लिक करें या अपने मौजूदा एसोसिएट से उनका रेफरल लिंक मांगें। अपने मूल विवरण के साथ रजिस्ट्रेशन फॉर्म भरें। रजिस्ट्रेशन के तुरंत बाद आपको अपना अद्वितीय रेफरल लिंक प्राप्त होगा।',
  'assoc_mlm_faq2_q' => 'मुझे भुगतान कब मिलता है?',
  'assoc_mlm_faq2_a' => 'प्लॉट बुकिंग के लिए भुगतान प्राप्त होने पर कमीशन स्वचालित रूप से गणना की जाती है। भुगतान मासिक बैचों में संसाधित किए जाते हैं। आप अपने डैशबोर्ड के कमीशन अनुभाग में अपनी सभी कमाई ट्रैक कर सकते हैं।',
  'assoc_mlm_faq3_q' => 'क्या कमाई पर कोई सीमा है?',
  'assoc_mlm_faq3_a' => 'हां, प्रति बिक्री कुल कमीशन बिक्री मूल्य के 20% तक सीमित है। यह सीमा स्थिरता सुनिश्चित करते हुए उत्कृष्ट कमाई क्षमता प्रदान करती है। VP+ रैंक के लिए 2% रॉयल्टी पूल इस सीमा के बाहर है।',
  'assoc_mlm_faq4_q' => 'क्या मैं अपनी रैंक खो सकता हूं?',
  'assoc_mlm_faq4_a' => 'नहीं — एक बार जब आप एक रैंक प्राप्त कर लेते हैं, तो आप इसे बनाए रखते हैं। रैंक केवल ऊपर जाती है, कभी नीचे नहीं। मासिक मूल्यांकन जांचता है कि क्या आप टीम के आकार और योग्यता वॉल्यूम के आधार पर अगली रैंक के लिए योग्य हैं।',
  'assoc_mlm_faq5_q' => 'प्रत्यक्ष कमीशन और डिफरेंशियल कमीशन में क्या अंतर है?',
  'assoc_mlm_faq5_a' => '<strong>प्रत्यक्ष कमीशन</strong> वह है जो बिक्री करने वाला एजेंट कमाता है (रैंक के आधार पर 5-20%)। <strong>डिफरेंशियल कमीशन</strong> वह है जो अपलाइन सदस्य कमाते हैं — उनकी रैंक की दर और प्रत्यक्ष एजेंट की दर के बीच का अंतर। उदाहरण के लिए, यदि आप BDM (10%) हैं और आपका डाउनलाइन एसोसिएट (5%) बिक्री करता है, तो आप 5% का अंतर कमाते हैं। कुल आपकी रैंक की दर से अधिक नहीं होता।',
  'assoc_mlm_faq6_q' => 'यदि बुकिंग रद्द हो जाए तो क्या होगा?',
  'assoc_mlm_faq6_a' => 'यदि बुकिंग रद्द की जाती है, तो उस बुकिंग के खिलाफ भुगतान किए गए सभी कमीशन वापस ले लिए जाते हैं (रिवर्स)। यह सिस्टम को निष्पक्ष रखता है और रद्द लेनदेन पर कमाई को रोकता है।',
  'assoc_mlm_your_ref_link' => 'आपका रेफरल लिंक',
  'assoc_mlm_share_desc' => 'अपनी टीम बढ़ाने के लिए इस लिंक को संभावित एसोसिएट्स के साथ साझा करें:',
  'assoc_mlm_copy' => 'कॉपी करें',
  'assoc_mlm_share_note' => 'जब कोई इस लिंक का उपयोग करके रजिस्टर करता है, तो वे आपके नेटवर्क में प्रत्यक्ष रेफरल के रूप में शामिल होते हैं।',
