  'assoc_rank_term1_q' => 'रैंक की गणना कैसे की जाती है?',
  'assoc_rank_term1_a' => 'रैंक की गणना <strong>आजीवन व्यावसायिक वॉल्यूम</strong> (कुल प्लॉट बिक्री मूल्य) और <strong>टीम आकार</strong> (प्रत्यक्ष लेग की संख्या) के आधार पर की जाती है। पदोन्नति के लिए दोनों मानदंड पूरे होने चाहिए। मूल्यांकन महीने के अंत में होता है।',
  'assoc_rank_term2_q' => 'मुझे मेरा रैंक पुरस्कार कब मिलेगा?',
  'assoc_rank_term2_a' => 'रैंक पुरस्कार <strong>30 दिनों</strong> के भीतर दिए जाते हैं, बशर्ते रैंक <strong>3 लगातार महीनों</strong> तक बनी रहे। पुरस्कार हस्तांतरणीय नहीं हैं और स्रोत पर कर कटौती के अधीन हैं।',
  'assoc_rank_term3_q' => '"प्रत्यक्ष लेग" क्या माना जाता है?',
  'assoc_rank_term3_a' => 'प्रत्यक्ष लेग वह एसोसिएट है जो आपके रेफरल कोड का उपयोग करके रजिस्टर किया है और कम से कम <strong>एक बिक्री</strong> की है। निष्क्रिय एसोसिएट्स (3 महीने में कोई बिक्री नहीं) टीम आवश्यकताओं की ओर नहीं गिने जाते।',
  'assoc_rank_term4_q' => 'क्या मैं अपनी रैंक खो सकता हूं?',
  'assoc_rank_term4_a' => 'हां। यदि आपका <strong>मासिक व्यावसायिक वॉल्यूम</strong> <strong>2 लगातार महीनों</strong> के लिए न्यूनतम सीमा से नीचे गिर जाता है, तो आपकी रैंक की समीक्षा की जाएगी। आपको ठीक होने के लिए 1 महीने की अनुग्रह अवधि दी जाएगी।',
  'assoc_rank_term5_q' => 'व्यावसायिक वॉल्यूम की गणना कैसे की जाती है?',
  'assoc_rank_term5_a' => 'व्यावसायिक वॉल्यूम में आपके और आपकी टीम द्वारा की गई सभी बुकिंग का <strong>कुल प्लॉट मूल्य</strong> शामिल है। केवल पुष्टि/पूर्ण बुकिंग गिनी जाती है। रद्द या रिफंड की गई बुकिंग को बाहर रखा गया है।',

